t", "text": "多人运动时关系分析遗漏"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略往返运动的方向变化"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "多次相遇有固定规律，第一次合走1个全程，之后每次多走2个全程。记住这个规律可以快速解题。"}]}]}]}$$ AS jsonb), NULL, '数量关系-行程问题-多人多次相遇的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "行程问题", "多人多次相遇"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_travel_multi_meet", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
